/**
 * Shared utilities for the classic-checkout Stripe Payment Elements bundles.
 *
 * Houses everything specific to the classic (shortcode) checkout — localised
 * params, page-detection helpers, hidden-input stitching, and Stripe SDK
 * singleton load. REST endpoint calls live in `../shared/api`, and the
 * wallet-checkout helpers live in `../shared/checkout`, so the block bundle
 * shares the same clients.
 *
 * @since 5.0.7
 */
import { loadStripe, type Stripe } from '@stripe/stripe-js';

import { HIDDEN_INPUT_NAME } from '../shared/checkout';

export { fetchPaymentIntent, resetPaymentIntent } from '../shared/api';
export type { PaymentIntentResponse as PaymentIntent } from '../shared/api';
export {
    HIDDEN_INPUT_NAME,
    wcAjaxUrl,
    wcAjaxPost,
    submitWalletCheckout,
    buildCheckoutFields,
    confirmWalletGesture,
} from '../shared/checkout';

export type DokanStripePeParams = {
    publishable_key: string;
    is_product?: 'yes' | 'no';
    is_cart?: 'yes' | 'no';
    is_checkout?: 'yes' | 'no';
    is_order_pay?: 'yes' | 'no';
    is_change_payment?: 'yes' | 'no';
    is_add_payment?: 'yes' | 'no';
    order_id?: number;
    order_key?: string;
    return_url?: string;
    locale?: string;
    currency?: string;
    cart_total_minor?: number;
    setup_future_usage?: '' | 'off_session' | 'on_session';
    wc_ajax_url?: string;
    checkout_nonce?: string;
};

export const params: DokanStripePeParams =
    ( window as any ).dokan_stripe_pe_params || {};

export const isProductPage = (): boolean => params.is_product === 'yes';
export const isCheckoutPage = (): boolean => params.is_checkout === 'yes';
export const isOrderPayPage = (): boolean => params.is_order_pay === 'yes';
export const isAddPaymentPage = (): boolean => params.is_add_payment === 'yes';

let stripeSingleton: Promise< Stripe | null > | null = null;

/**
 * Cache `loadStripe` so the SDK script only loads once across both bundles.
 */
export const loadStripeOnce = (): Promise< Stripe | null > => {
    if ( ! params.publishable_key ) {
        return Promise.resolve( null );
    }
    if ( ! stripeSingleton ) {
        stripeSingleton = loadStripe( params.publishable_key );
    }
    return stripeSingleton;
};

/**
 * Append (or replace) the hidden `dokan_stripe_payment_intent_id` input on a
 * form so server-side `process_payment()` routes to the PE branch.
 *
 * @param form
 * @param intentId
 */
export const appendIntentId = (
    form: HTMLFormElement,
    intentId: string
): void => {
    form.querySelectorAll( `input[name="${ HIDDEN_INPUT_NAME }"]` ).forEach(
        ( el ) => el.remove()
    );
    const input = document.createElement( 'input' );
    input.type = 'hidden';
    input.name = HIDDEN_INPUT_NAME;
    input.value = intentId;
    form.appendChild( input );
};

/**
 * Hidden field name for the DPS Stripe Subscription id (when the cart
 * contains a recurring `product_pack`). Read by gateway::process_payment
 * to persist `_stripe_subscription_id` on the order.
 */
export const SUBSCRIPTION_INPUT_NAME = 'dokan_stripe_subscription_id';

/**
 * Append (or replace) the hidden `dokan_stripe_subscription_id` input. No-op
 * when subscriptionId is empty so non-pack checkouts stay untouched.
 * @param form
 * @param subscriptionId
 */
export const appendSubscriptionId = (
    form: HTMLFormElement,
    subscriptionId: string | undefined
): void => {
    form.querySelectorAll(
        `input[name="${ SUBSCRIPTION_INPUT_NAME }"]`
    ).forEach( ( el ) => el.remove() );

    if ( ! subscriptionId ) {
        return;
    }

    const input = document.createElement( 'input' );
    input.type = 'hidden';
    input.name = SUBSCRIPTION_INPUT_NAME;
    input.value = subscriptionId;
    form.appendChild( input );
};
