/**
 * Dokan Stripe Connect — Payment Elements bundle for the shortcode checkout.
 *
 * Mounts a Stripe <PaymentElement> in `#dokan-stripe-connect-payment-element`,
 * calls stripe.confirmPayment on form submit, and appends the resulting PI id
 * as `dokan_stripe_payment_intent_id` so process_payment() routes to the PE
 * branch.
 *
 * @since 5.0.7
 */
import { type Stripe, type StripeElements } from '@stripe/stripe-js';

import {
    HIDDEN_INPUT_NAME,
    appendIntentId,
    appendSubscriptionId,
    confirmWalletGesture,
    fetchPaymentIntent,
    resetPaymentIntent,
    isAddPaymentPage,
    isOrderPayPage,
    loadStripeOnce,
    params,
    wcAjaxUrl,
} from './shared';

declare const jQuery: any;

const GATEWAY_ID = 'dokan-stripe-connect';
const MOUNT_ID = 'dokan-stripe-connect-payment-element';

let stripe: Stripe | null = null;
let elements: StripeElements | null = null;
let intentId: string | null = null;
let clientSecret: string | null = null;
let intentType: 'payment' | 'setup' = 'payment';
let subscriptionId: string | null = null;
// The payment method type currently selected in the Payment Element accordion
// (e.g. 'card', 'apple_pay', 'google_pay'). Updated via the element's `change`
// event; used to decide whether the wallet confirmation popup is needed.
let selectedPaymentType = '';

async function ensureStripe(): Promise< Stripe | null > {
    if ( stripe ) {
        return stripe;
    }
    stripe = await loadStripeOnce();
    return stripe;
}

async function mountPaymentElement() {
    const container = document.getElementById( MOUNT_ID );
    if ( ! container ) {
        return;
    }

    if (
        container.dataset.mounted === '1' &&
        elements &&
        elements.getElement( 'payment' )
    ) {
        return;
    }

    const stripeInstance = await ensureStripe();
    if ( ! stripeInstance ) {
        return;
    }

    if ( ! clientSecret ) {
        let fetchArgs: Parameters< typeof fetchPaymentIntent >[ 0 ] | undefined;

        if ( isAddPaymentPage() ) {
            fetchArgs = { context: 'add_payment_method' };
        } else if ( isOrderPayPage() ) {
            // Order-Pay + change-payment-method (both carry `pay_for_order`):
            // the intent is minted from the order, not the empty cart.
            fetchArgs = {
                context: 'order_pay',
                order_id: Number( params.order_id ) || 0,
                order_key: String( params.order_key ?? '' ),
            };
        }

        const intent = await fetchPaymentIntent( fetchArgs );
        if ( ! intent ) {
            return;
        }
        intentId = intent.intent_id;
        clientSecret = intent.client_secret;
        intentType = intent.type;
        subscriptionId = intent.subscription_id ?? null;
    }

    elements = stripeInstance.elements( {
        clientSecret,
        appearance: { theme: 'stripe' },
        locale: ( params.locale as any ) ?? 'auto',
    } );

    const paymentElement = elements.create( 'payment', {
        layout: {
            type: 'accordion',
            defaultCollapsed: false,
            radios: true,
            spacedAccordionItems: false,
        },
        paymentMethodOrder: [ 'card', 'apple_pay', 'google_pay', 'link' ],
    } );

    // Track the method the customer has selected in the accordion so the
    // place-order handler knows when a wallet (Apple Pay / Google Pay) is active
    // and must show the gesture-preserving confirmation popup (see runPlaceOrder).
    paymentElement.on( 'change', ( event: any ) => {
        selectedPaymentType = event?.value?.type ?? '';
    } );

    container.innerHTML = '';
    paymentElement.mount( '#' + MOUNT_ID );
    container.dataset.mounted = '1';
}

function resetMountState() {
    elements = null;
    clientSecret = null;
    intentId = null;
    resetPaymentIntent();
    const container = document.getElementById( MOUNT_ID );
    if ( container ) {
        container.dataset.mounted = '';
    }
}

function isGatewayChosen(): boolean {
    const input = document.querySelector< HTMLInputElement >(
        `input[name="payment_method"]:checked`
    );
    return input?.value === GATEWAY_ID;
}

function isUsingSavedToken(): boolean {
    const radio = document.querySelector< HTMLInputElement >(
        `input[name="wc-${ GATEWAY_ID }-payment-token"]:checked`
    );
    return !! radio && radio.value !== 'new';
}

async function runAddPaymentMethod( $form: any ): Promise< void > {
    $form.addClass( 'processing' );
    $form.block( {
        message: null,
        overlayCSS: { background: '#fff', opacity: 0.6 },
    } );

    try {
        // `redirect: 'always'` lets Stripe redirect to `return_url` with
        // `?setup_intent=seti_…&setup_intent_client_secret=…` appended. The
        // server-side `StripeCheckout::maybe_finalise_add_payment_method`
        // saves the token + redirects to the payment-methods list.
        const { error } = await stripe!.confirmSetup( {
            elements: elements!,
            confirmParams: {
                return_url: params.return_url || window.location.href,
            },
            redirect: 'always',
        } );

        if ( error ) {
            unblock( $form );
            // eslint-disable-next-line no-console
            console.warn( '[Dokan Stripe PE add-PM]', error.message );
            showInlineError( error.message ?? '' );
        }
    } catch ( e: any ) {
        unblock( $form );
        // eslint-disable-next-line no-console
        console.warn( '[Dokan Stripe PE add-PM]', e?.message );
        showInlineError( e?.message ?? 'Could not save payment method.' );
    }
}

async function runPlaceOrder( $form: any ): Promise< void > {
    $form.addClass( 'processing' );
    $form.block( {
        message: null,
        overlayCSS: { background: '#fff', opacity: 0.6 },
    } );

    try {
        // For Apple Pay / Google Pay, confirm via a fresh-gesture popup first so
        // Safari lets the wallet sheet open (see confirmWalletGesture). A no-op
        // for card / Link. Runs immediately before confirm so the activation the
        // popup grants is still live.
        if ( ! ( await confirmWalletGesture( selectedPaymentType ) ) ) {
            unblock( $form );
            return;
        }

        let confirmedId: string | null = null;

        if ( 'setup' === intentType ) {
            const { error, setupIntent } = await stripe!.confirmSetup( {
                elements: elements!,
                confirmParams: { return_url: window.location.href },
                redirect: 'if_required',
            } );

            if ( error ) {
                unblock( $form );
                // eslint-disable-next-line no-console
                console.warn( '[Dokan Stripe PE]', error.message );
                showInlineError( error.message ?? '' );
                return;
            }

            if (
                ! setupIntent ||
                ! [ 'succeeded', 'processing' ].includes( setupIntent.status )
            ) {
                unblock( $form );
                showInlineError( 'Could not save payment method.' );
                return;
            }

            confirmedId = setupIntent.id;
        } else {
            const { error, paymentIntent } = await stripe!.confirmPayment( {
                elements: elements!,
                confirmParams: { return_url: window.location.href },
                redirect: 'if_required',
            } );

            if ( error ) {
                unblock( $form );
                // eslint-disable-next-line no-console
                console.warn( '[Dokan Stripe PE]', error.message );
                showInlineError( error.message ?? '' );
                return;
            }

            if (
                ! paymentIntent ||
                ! [ 'succeeded', 'requires_capture', 'processing' ].includes(
                    paymentIntent.status
                )
            ) {
                unblock( $form );
                showInlineError( 'Payment could not be completed.' );
                return;
            }

            confirmedId = paymentIntent.id;
        }

        intentId = confirmedId;
        appendIntentId( $form[ 0 ], intentId );
        appendSubscriptionId( $form[ 0 ], subscriptionId ?? undefined );

        // Order-Pay / change-payment-method submit straight to the order-pay
        // endpoint — `wc-ajax=checkout` is cart-driven and invalid here. The
        // confirmed intent id rides along in the hidden input so the gateway's
        // process_payment() settles the existing order (or saves the new PM to
        // the subscription). A native submit bypasses the jQuery handlers.
        if ( isOrderPayPage() ) {
            ( $form[ 0 ] as HTMLFormElement ).submit();
            return;
        }

        jQuery
            .ajax( {
                url: wcAjaxUrl( 'checkout' ),
                method: 'POST',
                data: $form.serialize(),
                dataType: 'json',
            } )
            .done( ( response: any ) => {
                if ( response?.result === 'success' && response?.redirect ) {
                    const target =
                        typeof response.redirect === 'string'
                            ? response.redirect.replace( /^#.*:/, '' )
                            : window.location.href;
                    window.location.href = target;
                    return;
                }
                unblock( $form );
                const msg = Array.isArray( response?.messages )
                    ? response.messages.join( ' ' )
                    : response?.messages || 'Payment failed';
                showInlineError( msg );
            } )
            .fail( ( xhr: any ) => {
                unblock( $form );
                showInlineError(
                    xhr?.responseJSON?.messages ||
                        xhr?.statusText ||
                        'Network error'
                );
            } );
    } catch ( e: any ) {
        unblock( $form );
        // eslint-disable-next-line no-console
        console.warn( '[Dokan Stripe PE]', e?.message );
        showInlineError( e?.message ?? 'Payment could not be completed.' );
    }
}

function unblock( $form: any ) {
    $form.removeClass( 'processing' );
    if ( typeof $form.unblock === 'function' ) {
        $form.unblock();
    }
}

function showInlineError( message: string ) {
    const errorWrap = document.querySelector(
        '.woocommerce-NoticeGroup-checkout, .woocommerce-notices-wrapper'
    );
    if ( ! errorWrap ) {
        return;
    }

    if ( message.includes( 'woocommerce-error' ) ) {
        // Already-formed, server-generated WooCommerce notice markup.
        errorWrap.innerHTML = message;
    } else {
        // Plain message (e.g. a Stripe error string) — render as text so it
        // can never inject markup into the notice area.
        const list = document.createElement( 'ul' );
        list.className =
            'woocommerce_error woocommerce-error dokan-stripe-pe-error';
        const item = document.createElement( 'li' );
        item.textContent = message;
        list.appendChild( item );
        errorWrap.innerHTML = '';
        errorWrap.appendChild( list );
    }

    window.scrollTo( {
        top: ( errorWrap as HTMLElement ).offsetTop - 200,
        behavior: 'smooth',
    } );
}

const tryMount = () => {
    if ( ! isGatewayChosen() && ! isOrderPayPage() && ! isAddPaymentPage() ) {
        return;
    }
    // Saved-token radio selected → no PE mount, WC posts the token id
    // straight to the server-side TokenProcessor.
    if ( isUsingSavedToken() ) {
        return;
    }
    void mountPaymentElement();
};

const shouldIntercept = ( $form: any ): boolean => {
    if ( ! isGatewayChosen() ) {
        return false;
    }
    // Saved-token flow runs entirely server-side via TokenProcessor.
    if ( isUsingSavedToken() ) {
        return false;
    }
    if ( ! stripe || ! elements ) {
        return false;
    }
    // Already confirmed once — let WC proceed with the standard submit.
    if ( $form.find( `input[name="${ HIDDEN_INPUT_NAME }"]` ).length ) {
        return false;
    }
    return true;
};

const onPlaceOrder = (
    e: any,
    $form: any,
    preventDefault: boolean
): boolean => {
    if ( ! shouldIntercept( $form ) ) {
        return true;
    }
    if ( preventDefault ) {
        e.preventDefault();
        e.stopImmediatePropagation();
    }
    void runPlaceOrder( $form );
    return false;
};

jQuery( function ( $: any ) {
    if ( ! params || ! params.publishable_key ) {
        return;
    }

    $( document.body ).on( 'updated_checkout', () => {
        if ( ! isGatewayChosen() ) {
            return;
        }
        resetMountState();
        tryMount();
    } );

    $( document.body ).on( 'payment_method_selected', tryMount );

    $( document.body ).on(
        'change',
        `input[name="wc-${ GATEWAY_ID }-payment-token"]`,
        () => {
            resetMountState();
            void tryMount();
        }
    );

    if ( isOrderPayPage() || isAddPaymentPage() ) {
        tryMount();
    }

    if ( isAddPaymentPage() ) {
        $( 'form#add_payment_method' ).on(
            'submit',
            function ( this: HTMLFormElement, e: any ) {
                if ( ! stripe || ! elements ) {
                    return true;
                }
                e.preventDefault();
                e.stopImmediatePropagation();
                void runAddPaymentMethod( $( this ) );
                return false;
            }
        );
    }

    if ( params.is_checkout === 'yes' ) {
        // Some WC setups skip the initial `updated_checkout` event — schedule
        // an eager attempt once the gateway radios have rendered.
        setTimeout( tryMount, 0 );
        setTimeout( tryMount, 250 );
    }

    $( 'form.checkout' ).on(
        'submit',
        function ( this: HTMLFormElement, e: any ) {
            return onPlaceOrder( e, $( this ), true );
        }
    );

    $( 'form.checkout' ).on(
        'checkout_place_order_dokan-stripe-connect',
        function ( this: HTMLFormElement, e: any ) {
            return onPlaceOrder( e, $( this ), false );
        }
    );

    $( 'form#order_review' ).on(
        'submit',
        function ( this: HTMLFormElement, e: any ) {
            return onPlaceOrder( e, $( this ), true );
        }
    );
} );
