/**
 * Shared helpers for submitting a WC order via `wc-ajax=checkout` from an
 * Express Checkout wallet (Apple Pay / Google Pay / Link). Used by both the
 * classic and block bundles so they share a single mapping + submit path.
 *
 * @since 5.0.7
 */
import { __ } from '@wordpress/i18n';

export const HIDDEN_INPUT_NAME = 'dokan_stripe_payment_intent_id';

/**
 * Resolve a `wc-ajax=<action>` URL. Tries the classic params bag first, then
 * WC's own globals, then a static fallback so block context works too.
 *
 * @param action wc-ajax action name (e.g. `checkout`, `add_to_cart`).
 */
export const wcAjaxUrl = ( action: string ): string => {
    const fromParams = ( window as any ).dokan_stripe_pe_params?.wc_ajax_url;
    if ( typeof fromParams === 'string' ) {
        return fromParams.replace( '%%endpoint%%', action );
    }
    const fromCheckout = ( window as any ).wc_checkout_params?.wc_ajax_url;
    if ( typeof fromCheckout === 'string' ) {
        return fromCheckout.replace( '%%endpoint%%', action );
    }
    const fromCart = ( window as any ).wc_add_to_cart_params?.wc_ajax_url;
    if ( typeof fromCart === 'string' ) {
        return fromCart.replace( '%%endpoint%%', action );
    }
    return `${ window.location.origin }/?wc-ajax=${ action }`;
};

/**
 * POST a `wc-ajax=<action>` request via jQuery and resolve with the parsed
 * JSON body (or null on failure / when jQuery isn't loaded).
 *
 * @param action wc-ajax action name.
 * @param data   form fields to POST. jQuery serializes to form-urlencoded.
 */
export const wcAjaxPost = < T = unknown >(
    action: string,
    data: Record< string, unknown > = {}
): Promise< T | null > => {
    const $ = ( window as any ).jQuery;
    if ( ! $ ) {
        return Promise.resolve( null );
    }
    const url = wcAjaxUrl( action );
    return new Promise( ( resolve ) => {
        $.ajax( {
            url,
            method: 'POST',
            data,
            dataType: 'json',
        } )
            .done( ( json: T ) => {
                // Do not log the response — it can contain order keys and
                // billing PII and would ship in production builds.
                resolve( json );
            } )
            .fail( ( xhr: any ) => {
                // eslint-disable-next-line no-console
                console.warn(
                    `[Dokan Stripe] wc-ajax=${ action } failed (status ${
                        xhr?.status ?? 0
                    })`
                );
                resolve( null );
            } );
    } );
};

/**
 * Map Stripe `ExpressCheckoutElement` `onConfirm` event into WC checkout
 * form fields suitable for `wc-ajax=checkout`.
 *
 * @param intentId Confirmed Stripe PaymentIntent id.
 * @param event    Stripe `onConfirm` event payload.
 * @param nonce    WC `woocommerce-process_checkout` nonce.
 */
export const buildCheckoutFields = (
    intentId: string,
    event: any,
    nonce: string
): Record< string, string > => {
    const billing = event?.billingDetails ?? {};
    const billingAddr = billing.address ?? {};
    const shipping = event?.shippingAddress ?? {};
    const shippingAddr = shipping.address ?? {};

    const fullName: string = String( billing.name ?? shipping.name ?? '' );
    const [ firstName = '', ...rest ] = fullName.trim().split( /\s+/ );
    const lastName = rest.join( ' ' );

    // NOTE: do NOT include `woocommerce_checkout_update_totals` — WC stores
    // it as `isset()` (line 768 of class-wc-checkout.php), so the mere
    // presence of the field — even with value `'0'` — flips the branch on
    // line 1334 and tells WC to refresh totals instead of creating the order.
    const base: Record< string, string > = {
        payment_method: 'dokan-stripe-connect',
        [ HIDDEN_INPUT_NAME ]: intentId,
        terms: '1',
        'terms-field': '1',
        'woocommerce-process-checkout-nonce': nonce,
        _wpnonce: nonce,

        billing_first_name: firstName,
        billing_last_name: lastName,
        billing_email: billing.email ?? '',
        billing_phone: billing.phone ?? '',
        billing_address_1: billingAddr.line1 ?? '',
        billing_address_2: billingAddr.line2 ?? '',
        billing_city: billingAddr.city ?? '',
        billing_state: billingAddr.state ?? '',
        billing_postcode: billingAddr.postal_code ?? '',
        billing_country: billingAddr.country ?? '',
    };

    // Only attach shipping when the wallet actually returned one. WC validates
    // shipping fields aggressively when `ship_to_different_address=1`, so for
    // virtual carts we leave it `0` and let WC reuse billing.
    if ( event?.shippingAddress ) {
        const shipName: string = String( shipping.name ?? fullName );
        const [ shipFirst = firstName, ...shipRest ] = shipName
            .trim()
            .split( /\s+/ );
        const shipLast = shipRest.join( ' ' ) || lastName;

        base.ship_to_different_address = '1';
        base.shipping_first_name = shipFirst;
        base.shipping_last_name = shipLast;
        base.shipping_address_1 = shippingAddr.line1 ?? '';
        base.shipping_address_2 = shippingAddr.line2 ?? '';
        base.shipping_city = shippingAddr.city ?? '';
        base.shipping_state = shippingAddr.state ?? '';
        base.shipping_postcode = shippingAddr.postal_code ?? '';
        base.shipping_country = shippingAddr.country ?? '';
    } else {
        base.ship_to_different_address = '0';
    }

    if ( event?.shippingRate?.id ) {
        base[ 'shipping_method[0]' ] = String( event.shippingRate.id );
    }

    return base;
};

export type WalletCheckoutResult =
    | { ok: true; redirect: string }
    | { ok: false; message: string };

/**
 * Strip HTML tags from a WC notice string for surfacing in the wallet error
 * channel (which doesn't render HTML).
 *
 * @param html
 */
const stripHtml = ( html: string ): string =>
    html
        .replace( /<[^>]*>/g, ' ' )
        .replace( /\s+/g, ' ' )
        .trim();

/**
 * Submit a wallet-driven checkout via `wc-ajax=checkout`. Returns either the
 * redirect URL on success or the WC error message on failure so callers can
 * surface it to the user.
 *
 * @param intentId Confirmed Stripe PaymentIntent id.
 * @param event    Stripe `onConfirm` event payload.
 * @param nonce    WC `woocommerce-process_checkout` nonce.
 */
export const submitWalletCheckout = async (
    intentId: string,
    event: any,
    nonce: string
): Promise< WalletCheckoutResult > => {
    const fields = buildCheckoutFields( intentId, event, nonce );
    const json = await wcAjaxPost< {
        result?: string;
        redirect?: string;
        messages?: string;
    } >( 'checkout', fields );

    if ( json?.result === 'success' && json?.redirect ) {
        return { ok: true, redirect: String( json.redirect ) };
    }

    const message = json?.messages
        ? stripHtml( String( json.messages ) )
        : 'Checkout failed — no error message returned. Check WooCommerce logs (WP admin → WooCommerce → Status → Logs).';
    return { ok: false, message };
};

const WALLET_TYPES = [ 'apple_pay', 'google_pay' ];

/**
 * Whether a Payment Element method type is a wallet that opens its own sheet.
 *
 * @param type Payment method type from the element's `change` event.
 */
export const isWalletPaymentType = ( type: string ): boolean =>
    WALLET_TYPES.includes( type );

/**
 * Gate a wallet confirmation behind a fresh-gesture popup.
 *
 * Apple Pay / Google Pay must open their sheet from a direct user activation
 * (Safari/WebKit enforces this; Stripe otherwise throws "must be invoked
 * directly by a user activation event"). WooCommerce — both the classic
 * place-order pipeline and the Blocks onCheckoutSuccess event — runs async work
 * before `stripe.confirmPayment`, exhausting the original click's activation. So
 * for wallet methods we surface a small confirmation dialog first: the
 * customer's click on its "Proceed" button is a brand-new gesture, and
 * confirmPayment runs immediately after while that activation is still live.
 * Mirrors the approach used by the Stripe Express module.
 *
 * No-op (resolves true) for card / Link, or when the Dokan SweetAlert helper is
 * unavailable — there is nothing to gate on in those cases.
 *
 * @param type Payment method type currently selected in the Payment Element.
 *
 * @return Resolves true to proceed with confirmation, false if dismissed.
 */
export const confirmWalletGesture = async (
    type: string
): Promise< boolean > => {
    if ( ! isWalletPaymentType( type ) ) {
        return true;
    }

    const sweetalert = ( window as any ).dokan_sweetalert;
    if ( typeof sweetalert !== 'function' ) {
        return true;
    }

    const isApplePay = type === 'apple_pay';
    const result = await sweetalert(
        isApplePay
            ? __( 'Proceed to payment via Apple Pay?', 'dokan' )
            : __( 'Proceed to payment via Google Pay?', 'dokan' ),
        {
            action: 'confirm',
            confirmButtonText: __( 'Yes, Proceed', 'dokan' ),
            cancelButtonText: __( 'Cancel', 'dokan' ),
            confirmButtonColor: isApplePay ? '#363636' : '#1a73e8',
            cancelButtonColor: '#b54545',
        }
    );

    return ! result?.isDismissed;
};
